import heapq
from collections import Counter
from itertools import combinations


def _route_solver(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        start_mask = bit.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start = (data["source"], start_mask, 0)
        best = {start: data["start"]}
        queue = [(data["start"], start[0], start[1], start[2])]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != time:
                continue
            if (node == data["target"] and mask == full and
                    (not exact_coupons or used == data["coupons"])):
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], used)]
                if used < data["coupons"]:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, used + 1))
                for duration, next_used in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_state = (next_node, mask | bit.get(next_node, 0), next_used)
                    if arrival < best.get(next_state, float("inf")):
                        best[next_state] = arrival
                        heapq.heappush(queue, (arrival, *next_state))
        return {"arrival": None}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        constraints = {}
        for name, bounds in data["roots"].items():
            constraints.setdefault(name, []).append(tuple(bounds))
        best_vector = None
        best_versions = None

        def active_deps(row):
            return [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]

        def is_acyclic(selected):
            edges = {name: [dep["name"] for dep in active_deps(row)]
                     for name, row in selected.items()}
            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(selected, limits):
            nonlocal best_vector, best_versions
            for name, row in selected.items():
                if any(not low <= row["version"] <= high
                       for low, high in limits.get(name, [])):
                    return

            unresolved = [name for name in limits if name not in selected]
            if not unresolved:
                if not is_acyclic(selected):
                    return
                vector = tuple(selected[name]["version"] if name in selected else -1
                               for name in sorted(packages, reverse=True))
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_versions = {name: row["version"]
                                     for name, row in selected.items()}
                return

            name = unresolved[0]
            ranges = limits[name]
            rows = [row for row in packages.get(name, [])
                    if all(low <= row["version"] <= high for low, high in ranges)
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            for row in rows:
                next_selected = dict(selected)
                next_selected[name] = row
                next_limits = {key: list(value) for key, value in limits.items()}
                valid = True
                for dep in active_deps(row):
                    dep_name = dep["name"]
                    interval = (dep["min"], dep["max"])
                    next_limits.setdefault(dep_name, []).append(interval)
                    if (dep_name in next_selected and
                            not interval[0] <= next_selected[dep_name]["version"] <= interval[1]):
                        valid = False
                        break
                if valid:
                    search(next_selected, next_limits)

        search({}, constraints)
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = Counter(job["group"] for job in subset)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active_ends = []
            feasible = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"], row["id"])):
                while active_ends and active_ends[0] <= job["start"]:
                    heapq.heappop(active_ends)
                heapq.heappush(active_ends, job["end"])
                if len(active_ends) > 2:
                    feasible = False
                    break
            if not feasible:
                continue

            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


SOLVERS = {
    "component_01": _route_solver(2, True),
    "component_02": _route_solver(1, False),
    "component_03": _route_solver(1, True),
    "component_04": _route_solver(2, False),
    "component_05": _route_solver(2, True),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
